package dev.zomboid.mts;
import java.util.*;import minecrafttransportsimulator.entities.instances.*;
public class InspectionChecks {
 static int checks;static void check(boolean test,String message){checks++;if(!test)throw new AssertionError(message);}
 public static class Bounds {public Checks.Point globalCenter=new Checks.Point(0,0,0);public double widthRadius=2,heightRadius=1,depthRadius=3;}
 public static class Tag {Map<String,Long> data=new HashMap<>();public boolean contains(String key){return data.containsKey(key);}public long getLong(String key){return data.getOrDefault(key,0L);}public void putLong(String key,long v){data.put(key,v);}}
 public static class Entity {public long now;public boolean alive=true;public Tag tag=new Tag();public List<String> messages=new ArrayList<>();public Object level(){return this;}public long getGameTime(){return now;}public boolean isAlive(){return alive;}public Tag getPersistentData(){return tag;}public void displayClientMessage(net.minecraft.network.chat.Component text,boolean actionBar){messages.add(text.text);}}
 public static class Player extends Checks.Player implements minecrafttransportsimulator.mcinterface.IWrapperPlayer {public Entity entity=new Entity();public UUID id=UUID.randomUUID();public List<Object> packets=new ArrayList<>();public Checks.Point eye=new Checks.Point(0,0,0);public UUID getID(){return id;}public boolean isValid(){return true;}public Checks.Point getEyePosition(){return eye;}public void sendPacket(Object packet){packets.add(packet);}}
 public static void main(String[] args){check(!Inspection.finished(100,129),"cannot finish early");check(Inspection.finished(100,130),"30 ticks completes");check(Inspection.progress(100,115)==50,"halfway progress");EntityVehicleF_Physics car=new EntityVehicleF_Physics();PartSeat seat=new PartSeat();seat.vehicleOn=car;Player player=new Player();player.seat=seat;car.controller=player;Inspection.start(car,player);player.entity.now=10;Inspection.start(car,player);player.entity.now=29;Inspection.tick(car);check(player.packets.isEmpty(),"no GUI before 1.5 seconds");player.entity.now=30;Inspection.tick(car);check(player.packets.size()==1,"GUI opens once after timer");check(dev.survivorcreator.skills.Skills.total==5,"completed inspection grants real skill XP");Inspection.tick(car);check(player.packets.size()==1&&dev.survivorcreator.skills.Skills.total==5,"completion cannot repeat on next tick");player.entity.now=35;Inspection.start(car,player);player.entity.now=65;Inspection.tick(car);check(player.packets.size()==2&&dev.survivorcreator.skills.Skills.total==10,"each completed inspection grants XP");player.entity.now=6030;Inspection.start(car,player);player.entity.now=6060;Inspection.tick(car);check(dev.survivorcreator.skills.Skills.total==15,"later inspection also grants XP");Inspection.start(car,player);player.seat=null;player.eye=new Checks.Point(100,0,0);player.entity.now=6090;Inspection.tick(car);check(player.packets.size()==3,"moving out of range cancels inspection");check(Inspection.pending.isEmpty(),"cancelled task removed");player.eye=new Checks.Point(0,0,0);player.seat=seat;player.entity.now=7000;car.getOrCreateVariable("pz_inspect_request").setTo(1,true);Inspection.tick(car);check(!car.getOrCreateVariable("pz_inspect_request").isActive,"driver menu request consumed");player.entity.now=7030;Inspection.tick(car);check(player.packets.size()==4,"driver menu uses same timed path");System.out.println("Inspection server-flow checks: "+checks);}
}
